// Some portions generated by Codex
package org.eclipse.rdf4j.http.server.repository.transaction;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Map;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailTupleQuery;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class TransactionGraphAlgebraCompatibilityTest {
	@ParameterizedTest
	@EnumSource(GraphAlgebraMode.class)
	void workerUpdateExecutionKeepsTheSelectedAlgebra(GraphAlgebraMode mode) throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore()) {
			@Override
			public SailRepositoryConnection getConnection() {
				var connection = super.getConnection();
				connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(mode));
				return connection;
			}
		};
		repository.init();
		try {
			try (Transaction transaction = new Transaction(repository)) {
				transaction.setQueryParseOptions(QueryParseOptions.STRICT);
				transaction.begin();
				transaction.executeUpdate(QueryLanguage.SPARQL,
						"INSERT { <urn:result> <urn:p> <urn:o> } WHERE { GRAPH <urn:missing> {} }",
						null, true, null, Map.of());
				transaction.commit();
			}
			try (var connection = repository.getConnection()) {
				assertThat(connection.size()).isEqualTo(mode == GraphAlgebraMode.LEGACY ? 1 : 0);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void syntaxPolicyPreservesRepositoryModeOnTransactionWorker() throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore()) {
			@Override
			public SailRepositoryConnection getConnection() {
				var connection = super.getConnection();
				connection.setQueryParseOptions(
						QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
				return connection;
			}
		};
		repository.init();
		try (Transaction transaction = new Transaction(repository)) {
			transaction.setQueryParseOptions(QueryParseOptions.STRICT);
			var query = (SailTupleQuery) transaction.prepareQuery(QueryLanguage.SPARQL,
					"SELECT ?g WHERE { GRAPH ?g {} }", null);
			assertThat(query.getParsedQuery().getParseOptions().graphAlgebraMode())
					.isEqualTo(GraphAlgebraMode.LEGACY);
			assertThat(query.getParsedQuery().getParseOptions().blankNodeReferences()).isFalse();
		} finally {
			repository.shutDown();
		}
	}
}
